    private final Connection con;                 // borrowed from the caller

    public UsersGateway(Connection con) { this.con = con; }

    public Optional<UserRow> find(long id) throws SQLException {
        var sql = "SELECT id, name FROM users WHERE id = ?";
        try (var ps = con.prepareStatement(sql)) {
            ps.setLong(1, id);
            try (var rs = ps.executeQuery()) {
                return rs.next()
                    ? Optional.of(new UserRow(rs.getLong(1), rs.getString(2)))
                    : Optional.empty();
            }
        }
    }
}

