private final JdbcTemplate jdbc;
private final SimpleJdbcInsert insertUser =
    new SimpleJdbcInsert(jdbc).withTableName("users").usingGeneratedKeyColumns("id");

public Optional<UserRow> find(long id) {
    return jdbc.query("SELECT id, name FROM users WHERE id = ?",
                      rs -> rs.next() ? new UserRow(rs.getLong(1), rs.getString(2)) : null,
                      id).stream().findFirst();
}

public Number insert(UserRow u) {
    return insertUser.executeAndReturnKey(Map.of("name", u.name()));
}
